@spec tv_fx_region_spec  src=tests/specs/tv_fx_region_spec.lua  loc=1173  cases=60
@exercises dataStore (h.ds), trackerManager (h.tm), midiManager (h.fm), trackerView (h.vm), editCursor (h.ec), commandManager (h.cmgr), clipboard (h.clipboard)
@surface   ds:assign, tm:rebuild, ds:get, tm:addEvent, tm:flush, fm:dump, vm:setGridSize, vm:ppqToRow, ec:setPos, vm:fxHostForEdit, vm:noteFx, vm:setNoteFx, vm:removeFxStage, vm:addFxStage, vm:setFxField, ec:setSelection, vm:rowToPPQ, vm:fxHostAtCursor, cmgr:invoke, tm:getChannel, vm:editEvent, tm:subscribe, ec:row, ec:extendTo, clipboard:collect, vm:noteGhosts
@harness   mk

# Intent
  Track B (note macros v2): the fx-region column + Super-X addressing. A region
  renders as a tailed kind-badge in a per-channel fx column, and the v1 note-FX
  editor addresses it by uuid. see design/note-macros-v2.md § Authoring and editing the fx

# Helpers
  @fn injectRegion(h, over)  @ 16-21
  @fn fxColFor(h, chan)  @ 23-27
  @fn region(h, uuid)  @ 29-33
  @fn noteColIdx(h, chan, lane)  @ 35-39
  @fn addNote(h)  @ 41-45
  @fn authoredUuid(h)  @ 47-49
  @fn authoredPitches(h)  @ 53-60
      -- Pitches still sounding on the take (non-derived). Empty once a replace region has
      -- parked the covered chord off-take.

# Cases
  @case 'a region materialises a per-channel fx column with a badge + tail'  [harness]  @ 67-79
  @case 'a chain stacks its glyphs down the region rows in series order'  [harness]  @ 83-96
  @case 'a bypassed stage carries its flag down the stack'  [harness]  @ 100-110
  @case 'a chain longer than the region clips at the last row and marks it'  [harness]  @ 114-124
  @case 'a one-row region gives the clip mark the badge row'  [harness]  @ 128-136
  @case 'no region -> no fx column'  [harness]  @ 140-146
  @case 'an empty-fx region renders no column (it is an inert husk)'  [harness]  @ 150-156
  @case 'two overlapping regions pack into separate fx columns, each addressable'  [harness]  @ 162-190
  @case 'two disjoint regions share one fx column (packed into lane 1)'  [harness]  @ 194-206
  @case 'replace region: a parked note still renders in its note column'  [harness]  @ 212-224
  @case 'replace region: a parked cc still renders in its cc column'  [harness]  @ 228-251
  @case 'noteFx resolves a region uuid to its fx list'  [harness]  @ 257-262
  @case 'setNoteFx writes a region fx list back to ds'  [harness]  @ 266-272
  @case 'setNoteFx REMOVE deletes the region (a region is its fx)'  [harness]  @ 276-282
  @case 'region fx: deselecting the last kind keeps a husk the editor can repopulate'  [harness]  @ 286-296
  @case 'setFxField edits one region fx field, leaving the region'  [harness]  @ 300-306
  @case 'fxHostForEdit: caret on an fx cell returns the region uuid'  [harness]  @ 312-320
  @case 'fxHostForEdit: a selection mints a replace region over its span'  [harness]  @ 324-338
  @case 'fxHostAtCursor: a selection does not mint -- cursor movement has no side effect'  [harness]  @ 342-350
  @case 'fxHostAtCursor: caret anywhere in an fx region returns its uuid, nil past the tail'  [harness]  @ 354-367
  @case 'fxHostForEdit: off a note with no selection is nil; on a note, its uuid (v1)'  [harness]  @ 371-381
  @case 'parked note: a pitch nudge edits the off-take stash and re-renders, still parked'  [harness]  @ 387-401
  @case 'parked note: delete removes it from the stash and does not restore it when the window moves off'  [harness]  @ 405-416
  @case 'parked add: typing a note into a replace window stashes a logical spec, off the take'  [harness]  @ 420-434
  @case 'parked move-out: nudging a parked note past the window end restores it to the take'  [harness]  @ 438-451
  @case 'parked cc: a value nudge edits the off-take cc stash; delete removes it'  [harness]  @ 455-487
  @case 'parked pb: a value nudge edits the off-take pb stash; delete removes it'  [harness]  @ 491-527
  @case 'multi-select spanning a parked note and a take note: both edit under one rebuild'  [harness]  @ 531-552
  @case 'fx noteOff truncates the region tail to the cursor row'  [harness]  @ 558-570
  @case 'fx noteOff finds the right region in its lane when cells are in storage, not ppq, order'  [harness]  @ 574-588
  @case 'fx noteOff past the region tail grows it to the cursor row'  [harness]  @ 592-601
  @case 'fx noteOff on the onset row is a no-op (deletion is the delete verb, not noteOff)'  [harness]  @ 605-616
  @case 'fx noteOff on the window end row re-opens it to the pattern length'  [harness]  @ 620-630
  @case 'fx growNote / shrinkNote resize the region from its end'  [harness]  @ 634-645
  @case 'fx nudgeForward shifts the whole window and the caret follows'  [harness]  @ 649-661
  @case 'fx nudge keeps the moved region in its lane; the newly-overlapped sibling displaces right'  [harness]  @ 665-687
  @case 'fx nudge of an already-overlapping region keeps its own higher lane (no reorder)'  [harness]  @ 691-710
  @case 'fx nudge that makes an overlap disjoint tracks the caret across the column merge'  [harness]  @ 714-734
  @case 'fx window edit on a disjoint region does not churn storage order'  [harness]  @ 738-754
  @case 'fx nudgeBack refuses at the top grid edge (window unchanged)'  [harness]  @ 758-769
  @case 'fx eventShiftLeft swaps the region one lane left, flipping storage precedence'  [harness]  @ 775-799
  @case 'fx eventShiftRight swaps the region one lane right (the inverse move)'  [harness]  @ 803-818
  @case 'fx eventShift is a no-op at the grid edge (lone region, nothing beside it)'  [harness]  @ 822-834
  @case 'fx eventShift no-ops when the adjacent lane is empty at the cursor row'  [harness]  @ 838-853
  @case 'parked note: noteOff shortens its tail in the stash, stays parked'  [harness]  @ 859-872
  @case 'parked note: a time nudge within the window retimes the stash, stays parked'  [harness]  @ 876-889
  @case 'fx copy captures a region by onset; the whole window rides, tail spilling past the band'  [harness]  @ 895-913
  @case 'fx copy skips a region that only passes through the band (onset above it)'  [harness]  @ 917-926
  @case 'fx copy + paste stacks a duplicate region at the cursor row, original intact'  [harness]  @ 930-950
  @case 'fx delete removes the region under the caret'  [harness]  @ 954-963
  @case 'fx deleteSel drops every region the rectangle catches (onset in band), sparing the rest'  [harness]  @ 967-984
  @case 'fx freeze promotes the region output to authored notes and drops the region'  [harness]  @ 990-1002
  @case 'fx freeze converts an fx-carrying note at the caret'  [harness]  @ 1006-1018
  @case 'fx freeze declines on a plain note (no chain to freeze)'  [harness]  @ 1022-1032
  @case 'fx freeze: a refused freeze opens no undo block; an eligible one opens exactly one'  [harness]  @ 1039-1076
  @case 'noteGhosts: no host under the caret returns nil, before any window query'  [harness]  @ 1082-1091
  @case 'noteGhosts: a host lights its derived onsets on the lane column, with pitch and vel'  [harness]  @ 1095-1120
  @case 'noteGhosts: a host whose onsets lie outside the window answers empty, not nil'  [harness]  @ 1124-1136
  @case 'noteGhosts: a row carrying a real cell still reports its ghost -- precedence is the draw arm\'s'  [harness]  @ 1140-1152
  @case 'noteGhosts: the window is the viewport -- onsets below it are absent'  [harness]  @ 1156-1171

